sys_security_acl.script:
(function() {
    // Grant access to users with problem_manager, itil, or problem_admin role
    // Adjust these roles based on your organization's needs

    if (gs.hasRole('problem_manager') || 
        gs.hasRole('itil') || 
        gs.hasRole('problem_admin') ||
        gs.hasRole('admin')) {
        return true;
    }

    // Deny access to all other users
    return false;
})();
